import React, { useEffect, useState } from 'react';
import { getCars } from '../services/carService';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

const CatalogPage = () => {
  const [cars, setCars] = useState([]);
  const [brand, setBrand] = useState('');
  const [minPrice, setMinPrice] = useState('');
  const [maxPrice, setMaxPrice] = useState('');

  useEffect(() => {
    fetchCars();
  }, []);

  const fetchCars = async (filters = {}) => {
    try {
      const res = await getCars(filters);
      setCars(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleFilter = (e) => {
    e.preventDefault();
    const filters = {};
    if (brand) filters.brand = brand;
    if (minPrice) filters.min_price = minPrice;
    if (maxPrice) filters.max_price = maxPrice;
    fetchCars(filters);
  };

  return (
    <div style={{ padding: '2rem' }}>
      <h1>Каталог автомобилей</h1>
      <form onSubmit={handleFilter} style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
        <input placeholder="Марка" value={brand} onChange={(e) => setBrand(e.target.value)} />
        <input placeholder="Мин. цена" type="number" value={minPrice} onChange={(e) => setMinPrice(e.target.value)} />
        <input placeholder="Макс. цена" type="number" value={maxPrice} onChange={(e) => setMaxPrice(e.target.value)} />
        <button type="submit">Фильтровать</button>
      </form>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '2rem' }}>
        {cars.map((car) => (
          <motion.div key={car.id} whileHover={{ scale: 1.03 }} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
            <Link to={`/cars/${car.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
              <div style={{ background: 'white', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
                <img src={car.image_url || '/images/default-car.jpg'} alt={car.model} style={{ width: '100%', height: '180px', objectFit: 'cover' }} />
                <div style={{ padding: '1rem' }}>
                  <h3>{car.brand} {car.model}</h3>
                  <p>{car.year} – {car.price.toLocaleString()} ₽</p>
                </div>
              </div>
            </Link>
          </motion.div>
        ))}
      </div>
    </div>
  );
};

export default CatalogPage;
